ALTER TABLE players ALTER COLUMN "birthDate" DROP NOT NULL;
CREATE TABLE categories(id uuid PRIMARY KEY,name text NOT NULL UNIQUE,"sortOrder" integer NOT NULL,"minAge" integer NOT NULL,"maxAge" integer,"scoringEnabled" boolean NOT NULL,notes text NOT NULL);
CREATE TABLE team_details(id uuid PRIMARY KEY,"teamId" uuid NOT NULL UNIQUE REFERENCES teams(id),"categoryId" uuid NOT NULL REFERENCES categories(id),"yearGroup" integer NOT NULL CHECK("yearGroup" BETWEEN 0 AND 2),"groupCode" text NOT NULL,division text NOT NULL,"isExample" boolean NOT NULL);
CREATE TABLE player_details(id uuid PRIMARY KEY,"playerId" uuid NOT NULL UNIQUE REFERENCES players(id),"joinedAt" date,"leftAt" date,"reviewedAt" timestamptz,"selfResponsible" boolean NOT NULL,"photoUrl" text NOT NULL,position text NOT NULL,source text NOT NULL,"isExample" boolean NOT NULL,"erasedAt" timestamptz);
CREATE TABLE matches(id uuid PRIMARY KEY,"seasonId" uuid NOT NULL REFERENCES seasons(id),"teamId" uuid NOT NULL,"startsAt" timestamptz NOT NULL,"endsAt" timestamptz NOT NULL,opponent text NOT NULL,venue text NOT NULL CHECK(venue IN ('HOME','AWAY')),location text NOT NULL,competition text NOT NULL,status text NOT NULL CHECK(status IN ('SCHEDULED','FINAL','CANCELLED')),"scoreFor" integer,"scoreAgainst" integer,published boolean NOT NULL,"isExample" boolean NOT NULL,CHECK("startsAt"<"endsAt"),CHECK("scoreFor" IS NULL OR "scoreFor">=0),CHECK("scoreAgainst" IS NULL OR "scoreAgainst">=0),FOREIGN KEY("teamId","seasonId") REFERENCES teams(id,"seasonId"));
CREATE TABLE player_requests(id uuid PRIMARY KEY,"seasonId" uuid NOT NULL REFERENCES seasons(id),"teamId" uuid NOT NULL,"requestedBy" text NOT NULL,kind text NOT NULL CHECK(kind IN ('TRAINING','MATCH')),"sessionId" uuid REFERENCES sessions(id),"matchId" uuid REFERENCES matches(id),"neededAt" timestamptz NOT NULL,quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 20),reason text NOT NULL,status text NOT NULL CHECK(status IN ('PENDING','APPROVED','REJECTED')),recurring boolean NOT NULL,"createdAt" timestamptz NOT NULL,"resolvedAt" timestamptz,"decisionNote" text NOT NULL,FOREIGN KEY("teamId","seasonId") REFERENCES teams(id,"seasonId"),CHECK((kind='MATCH' AND "matchId" IS NOT NULL AND NOT recurring) OR (kind='TRAINING' AND "sessionId" IS NOT NULL)));
CREATE TABLE request_players(id uuid PRIMARY KEY,"requestId" uuid NOT NULL REFERENCES player_requests(id),"playerSeasonId" uuid NOT NULL REFERENCES player_seasons(id),UNIQUE("requestId","playerSeasonId"));
CREATE TABLE notifications(id uuid PRIMARY KEY,"recipientUid" text,"adminOnly" boolean NOT NULL,"teamId" uuid REFERENCES teams(id),title text NOT NULL,body text NOT NULL,href text NOT NULL,"createdAt" timestamptz NOT NULL,"readBy" text[] NOT NULL,"dedupeKey" text NOT NULL UNIQUE);
CREATE TABLE magazines(id uuid PRIMARY KEY,title text NOT NULL,description text NOT NULL,"pdfPath" text NOT NULL,"publishedAt" timestamptz,published boolean NOT NULL,"isExample" boolean NOT NULL);
CREATE TABLE club_activities(id uuid PRIMARY KEY,title text NOT NULL,description text NOT NULL,"startsAt" timestamptz NOT NULL,location text NOT NULL,"imageUrl" text NOT NULL,published boolean NOT NULL,"isExample" boolean NOT NULL);
CREATE TABLE coach_details(id uuid PRIMARY KEY,"coachId" uuid NOT NULL UNIQUE REFERENCES coaches(id),"photoUrl" text NOT NULL,"isExample" boolean NOT NULL);
CREATE INDEX matches_team_date ON matches("teamId","startsAt");
CREATE INDEX requests_status ON player_requests(status,"neededAt");
CREATE INDEX notifications_created ON notifications("createdAt");
CREATE UNIQUE INDEX one_head_coach ON coach_teams("teamId") WHERE function='HEAD';
CREATE UNIQUE INDEX one_assistant_coach ON coach_teams("teamId") WHERE function='ASSISTANT';
